{
  "name": "@digi4care/mnemosyne-opencode",
  "version": "0.5.1",
  "description": "Automatic, per-project long-term memory for OpenCode, backed by Mnemosyne",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "mnemosyne",
    "memory",
    "agent-memory",
    "llm"
  ],
  "homepage": "https://github.com/digi4care/mnemosyne-opencode#readme",
  "bugs": {
    "url": "https://github.com/digi4care/mnemosyne-opencode/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/digi4care/mnemosyne-opencode.git"
  },
  "license": "MIT",
  "author": "Chris Engelhard <chris@chrisengelhard.nl>",
  "contributors": [
    "Chris Engelhard <chris@chrisengelhard.nl> (https://github.com/digi4care)"
  ],
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": "./index.js",
    "./server": "./index.js",
    "./v1-server": "./v1-server.js",
    "./tui": "./tui.js",
    "./v1-tui": "./v1-tui.js"
  },
  "engines": {
    "node": ">=22.19.0"
  },
  "files": [
    "index.js",
    "v1-server.js",
    "v1-tui.js",
    "tui.js",
    "memory_worker.py",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test --test-concurrency=1"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.29",
    "jsonc-parser": "^3.3.1"
  }
}
